 t text; n jsonb; op jsonb; d jsonb; k text; old text; nw text; ct text; ut text; wj text; wu text; kv record; nl int:=0; ns int:=0;
begin
 foreach t in array array['team','pub'] loop
  execute format('create table if not exists public.%I as table public.%I','bkp_'||t||'_20261112',t);
  select data_type into ct from information_schema.columns where table_schema='public' and table_name=t and column_name='j';
  select data_type into ut from information_schema.columns where table_schema='public' and table_name=t and column_name='u';
  wj := case when ct='jsonb' then 'to_jsonb($2::text)' when ct='json' then 'to_json($2::text)' else '$2' end;
  wu := case when ut like 'timestamp%' then 'now()' else '(extract(epoch from clock_timestamp())*1000)::bigint' end;
  -- 1) versões novas (cópia da música-base com o medley da planilha)
  for n in select * from jsonb_array_elements(spec->'new') loop
   execute format('select to_jsonb(j) from public.%I where id=$1',t) into d using 's_'||(n->>'base');
   if d is null then raise notice '[%] música-base % não encontrada, pulei %',t,n->>'base',n->>'id'; continue; end if;
   if jsonb_typeof(d)='string' then d := (d #>> '{}')::jsonb; end if;
   d := (d - 'hist' - 'rev') || jsonb_build_object('id',n->>'id','medleys',n->'medleys','mlinks',n->'mlinks');
   if jsonb_typeof(n->'martists')='array' then d := d || jsonb_build_object('martists',n->'martists'); end if;
   if (n->>'dropmed')::boolean and jsonb_typeof(d->'parts')='array' then
    d := jsonb_set(d,'{parts}',coalesce((select jsonb_agg(p order by i) from jsonb_array_elements(d->'parts') with ordinality x(p,i) where coalesce(p->>'type','') !~* 'medley'),'[]'::jsonb));
   end if;
   execute format('insert into public.%I (id,j,u) values ($1,%s,%s) on conflict (id) do update set j=excluded.j,u=excluded.u',t,wj,wu) using 's_'||(n->>'id'), d::text;
   ns := ns+1;
  end loop;
  -- 2) cultos
  for op in select * from jsonb_array_elements(spec->'ops') loop
   execute format('select to_jsonb(j) from public.%I where id=$1',t) into d using 'l_'||(op->>'id');
   if d is null then raise notice '[%] culto % não encontrado',t,op->>'id'; continue; end if;
   if jsonb_typeof(d)='string' then d := (d #>> '{}')::jsonb; end if;
   for old,nw in select key,value from jsonb_each_text(op->'ren') loop
    for k in select key from jsonb_each(d) where jsonb_typeof(value)='object' and key<>'banda' and value ? old loop
     d := jsonb_set(d,array[k],((d->k) - old) || jsonb_build_object(nw,d->k->old));
    end loop;
    if jsonb_typeof(d->'rot')='array' then
     d := jsonb_set(d,'{rot}',coalesce((select jsonb_agg(case when e->>'a'=old then e||jsonb_build_object('a',nw) else e end order by i) from jsonb_array_elements(d->'rot') with ordinality x(e,i)),'[]'::jsonb));
    end if;
   end loop;
   d := d || jsonb_build_object('songIds',op->'songIds','ord',op->'ord');
   if jsonb_typeof(d->'keys') is distinct from 'object' then d := d || '{"keys":{}}'::jsonb; end if;
   for kv in select key,value from jsonb_each(op->'keys') loop
    if jsonb_typeof(kv.value)='null' then d := jsonb_set(d,'{keys}',(d->'keys') - kv.key);
    else d := jsonb_set(d,array['keys',kv.key],kv.value); end if;
   end loop;
   execute format('update public.%I set j=%s,u=%s where id=$1',t,wj,wu) using 'l_'||(op->>'id'), d::text;
   nl := nl+1;
  end loop;
 end loop;
 raise notice 'Pronto: % cultos e % versões gravados (somando as duas tabelas).',nl,ns;
end $fv$;
select 'ok: repertórios iguais à planilha' as status;
